export const previewLocalDirPrevLine = '原来的位置：~/Desktop/旧版活动报名页'
/**
 * P81r1 的预览入口 ?job=localdir：在 B2 样例后面再接一张约定卡。
 * 第一张写「已有文件夹」（localDirLine 带后缀）；第二张同样，并多一行「原来的位置」（localDirPrevLine）。
 * 只是预览样例（结构化克隆后改视图字段），不改快照本身。
 */
export function previewLocalDirCardsThread(): ThreadView {
  const thread = structuredClone(previewB2Thread)
  const cardMessage = thread.messages.at(-1)
  if (cardMessage?.agreement == null) return thread
  cardMessage.agreement.launchLine = `验收之后对外发布：${previewLocalHow}。发布前单独请你批准。`
  cardMessage.agreement.localDirLine = previewLocalDirFilesLine
  const second = structuredClone(cardMessage)
  second.id = 'm_sampleb2c2'
  if (second.agreement != null) second.agreement.localDirPrevLine = previewLocalDirPrevLine
  thread.messages.push(second)
  return thread
}
